ENTRY(_start)

MEMORY
{
	flash  (wx) : ORIGIN = 0x01000000, LENGTH = 0x01000000 /* 2^24 =  16MB */
	sdram  (wx) : ORIGIN = 0x10000000, LENGTH = 0x10000000 /* 2^28 = 256MB */
}

_flash	= ORIGIN(flash);
_blkram	= 0;
_sdram	= ORIGIN(sdram);
_top_of_stack = ORIGIN(sdram) + LENGTH(sdram) - 4;

SECTIONS
{
	.rocode ORIGIN(flash) : {
		_boot_address = .;
		*(.start)
		} > flash
	_kernel_image_start = . ;
	_kernel_image_end = . ;
	_sdram_image_start = . ;
	.ramcode ORIGIN(sdram) : {
		*(.kernel)
		*(.text.startup)
		*(.text)
		*(.rodata*) *(.strings)
		*(.data) *(COMMON)
		}> sdram AT> flash
	_sdram_image_end = . ;
	.bss : {
		*(.bss)
		_bss_image_end = . ;
		} > sdram
	_top_of_heap = .;
}

